import React, { useState } from 'react';

// Create the App component here
const App = () => {
  // Initialize count state here
  const [count, setCount] = useState(0);
  const [intervalId, setIntervalId] = useState(null);

  // Define startTimer function here
  const startTimer = () => {
    const id = setInterval(() => {
      setCount(prev => prev + 1);
    }, 1000);
    setIntervalId(id);
  };

  // Define stopTimer function here
  const stopTimer = () => {
    clearInterval(intervalId);
    setIntervalId(null);
  };

  return (
    <div>
      <h1>Memory Leak Hunt</h1>
      <p>Count: {count}</p>
      <button onClick={startTimer}>Start Timer</button>

    </div>
  );
};

export default App;

